Here's a complete example with both `DataRow` and `DynamicData` (ValueTuple) patterns for your `PriceCalculator`:

```csharp
// PriceCalculator.cs
public class PriceCalculator
{
    public decimal CalculateTotal(decimal unitPrice, int quantity)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(unitPrice);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(quantity);
        return unitPrice * quantity;
    }

    public decimal ApplyDiscount(decimal price, int discountPercent)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(price);
        if (discountPercent < 0 || discountPercent > 100)
            throw new ArgumentOutOfRangeException(nameof(discountPercent));
        return price - (price * discountPercent / 100m);
    }
}
```

```csharp
// PriceCalculatorTests.cs
[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    // ── CalculateTotal: DataRow for simple inline cases ──

    [TestMethod]
    [DataRow(10.00, 1, 10.00, DisplayName = "Single item")]
    [DataRow(10.00, 3, 30.00, DisplayName = "Multiple items")]
    [DataRow(0.00, 5, 0.00,   DisplayName = "Zero price")]
    [DataRow(9.99, 2, 19.98,  DisplayName = "Fractional price")]
    public void CalculateTotal_ValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    public void CalculateTotal_NegativePrice_Throws()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(-1m, 1));
        Assert.AreEqual("unitPrice", ex.ParamName);
    }

    [TestMethod]
    [DataRow(0,  DisplayName = "Zero quantity")]
    [DataRow(-1, DisplayName = "Negative quantity")]
    public void CalculateTotal_InvalidQuantity_Throws(int quantity)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(10m, quantity));
    }

    // ── ApplyDiscount: DynamicData with ValueTuples for decimal precision ──

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_ValidInputs_ReturnsExpected(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int discountPercent, decimal expected)>
        DiscountTestData =>
    [
        (100m, 10, 90m),
        (200m, 25, 150m),
        (50m,  0,  50m),
        (80m, 100, 0m),
        (0m,   50, 0m),
        (99.99m, 15, 84.9915m),
    ];

    [TestMethod]
    [DataRow(-1, DisplayName = "Below zero")]
    [DataRow(101, DisplayName = "Above 100")]
    public void ApplyDiscount_InvalidPercent_Throws(int discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, discountPercent));
    }

    [TestMethod]
    public void ApplyDiscount_NegativePrice_Throws()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(-10m, 10));
        Assert.AreEqual("price", ex.ParamName);
    }
}
```

**Key patterns used:**

- **`DataRow`** — inline values for simple types (`double`/`int`); note `decimal` isn't allowed in attributes, so we pass `double` and cast
- **`DynamicData` with ValueTuples** — preferred for `decimal` precision and complex data (MSTest 3.7+); type-safe, no `object[]` boxing
- **`Assert.ThrowsExactly<T>`** — modern exception testing (not `[ExpectedException]`)
- **`DisplayName`** — makes test explorer output readable
- **Sealed class**, constructor init, AAA structure

For your project setup, use `MSTest.Sdk` or the `MSTest` metapackage (v3.8+) to get all these features and the built-in analyzers.
